public static int calculateTimeNeeded(int N) {
    if (N <= 1) {
        return 0; // No time needed for 0 or 1 person
    }
    if (N <= 3) {
        return 1; // Only one pair to swap for 2 or 3 people
    }
    // For more than 3 people, calculate the number of adjacent swaps needed
    // which is essentially (N-1) swaps
    return 2 * (N - 2);
}

