public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles, only the plane itself is the region
    }
    // The formula to calculate the maximum number of regions
    // formed by N triangles is derived from the fact that each new triangle
    // can intersect all previous triangles to form the maximum number of new regions.
    // The formula is R(N) = 2 * N^2 + 2 * N + 1
    return 2 * N * N + 2 * N + 1;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles N must be non-negative.");
    }

    // Base case: with 0 triangles, there is 1 region (the whole plane)
    if (N == 0) {
        return 1;
    }

    // Base case: with 1 triangle, it divides the plane into 2 regions
    if (N == 1) {
        return 2;
    }

    // General case: each new triangle can intersect all previous triangles
    // in at most 2 points, creating 2 new regions for each intersection
    // plus the triangle itself adding 1 additional region.
    // The formula derived is: 2 + 2 * (N * (N + 1) / 2)
    // Simplified: 1 + N * (N + 1)
    return 1 + N * (N + 1);
}

public static int maxRegions(int N) {
    if (N < 0) {
