    }
    // The maximum number of regions R(N) for N triangles can be calculated using the formula:
    // R(N) = N * (N + 1) / 2 + 1
    // This formula is derived from the pattern observed in the division of the plane by triangles.
    return N * (N + 1) / 2 + 1;
}

