public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Words cannot be null");
    }

    // Convert words to lowercase to ensure case insensitivity
    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    // Use a boolean array to track letters in word1
    boolean[] lettersInWord1 = new boolean[26];
    for (char c : word1.toCharArray()) {
        lettersInWord1[c - 'a'] = true;
    }

    int commonLetters = 0;
    for (char c : word2.toCharArray()) {
        if (lettersInWord1[c - 'a']) {
            commonLetters++;
            lettersInWord1[c - 'a'] = false; // Ensure each letter is only counted once
        }
    }

    int totalLength = word1.length() + word2.length();
    if (totalLength == 0) {
        return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = 0/1";
    }

    // Find the greatest common divisor (GCD) to reduce the fraction
    int gcd = gcd(commonLetters, totalLength);

    // Reduce the fraction
    int reducedNumerator = commonLetters / gcd;
    int reducedDenominator = totalLength / gcd;

    return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + reducedNumerator + "/" + reducedDenominator;
}

