    word2 = word2.toUpperCase();

    int commonCount = 0;
    boolean[] used = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        char currentChar = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (!used[j] && word2.charAt(j) == currentChar) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(commonCount, totalLength);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (totalLength / gcd);
}

public static String convertDatesToWeekdays(String date) {
    String[] monthNames = {"January", "February", "March", "April", "May", "June", 
                           "July", "August", "September", "October", "November", "December"};
    String[] dayNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date format must be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]) - 1; // month index is 0-based
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 0 || month > 11) {
            throw new IllegalArgumentException("Month must be between 01 and 12");
        }

        // Leap year checking
        boolean isLeapYear = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        int[] daysInMonth = {31, (isLeapYear ? 29 : 28), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        if (day < 1 || day > daysInMonth[month]) {
            throw new IllegalArgumentException("Invalid day for the given month and year");
        }

        // Calculate the day of the week
        int[] t = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4};
        year -= month < 2 ? 1 : 0;
        int weekdayIndex = (year + year/4 - year/100 + year/400 + t[month] + day) % 7;

        return monthNames[month] + " " + day + ", " + year + " is a " + dayNames[weekdayIndex];

    } catch (NumberFormatException e) {
        return "Invalid date format. Please use 'MM dd yyyy'";
    } catch (IllegalArgumentException e) {
        return e.getMessage();
    }
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] dateParts = date.split(" ");
        if (dateParts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        if (month < 1 || month > 12 || day < 1 || day > 31) {
            return "Invalid date values";
        }

        String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);
        int dayOfWeek = calendar.get(java.util.Calendar.DAY_OF_WEEK);

        return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[dayOfWeek - 1];
    } catch (NumberFormatException e) {
        return "Invalid date format";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.isEmpty()) {
        return "Invalid date format";
    }

    String[] parts = date.split(" ");
    if (parts.length != 3) {
        return "Invalid date format";
    }

    String[] months = {"January", "February", "March", "April", "May", "June",
                        "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    try {
        int month = Integer.parseInt(parts[0]) - 1; // Array index starts from 0
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 0 || month > 11 || day < 1 || day > 31 || year < 0) {
            return "Invalid date values";
        }

        // Zeller's Congruence Algorithm to find the day of the week
        int k = year % 100;
        int j = year / 100;
        int f = day + (13 * (month + 1)) / 5 + k + k / 4 + j / 4 + 5 * j;
        int dayOfWeek = f % 7;

        // Adjust for Zeller's algorithm starting on Saturday
        if (dayOfWeek == 0) {
            dayOfWeek = 7;
        }

        return months[month] + " " + day + ", " + year + " is a " + weekdays[dayOfWeek - 1];

    } catch (NumberFormatException e) {
        return "Invalid date format";
    }
}

