public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] dp = new boolean[n / 2 + 1][sum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int j = 0; j <= sum - num; j++) {
                if (dp[i - 1][j]) {
                    dp[i][j + num] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int k = 1; k <= n / 2; k++) {
        for (int i = 1; i <= n; i++) {
            for (int s = 0; s <= sum; s++) {
                dp[k][i][s] = dp[k][i - 1][s];
                if (s >= nums[i - 1] && dp[k - 1][i - 1][s - nums[i - 1]]) {
                    dp[k][i][s] = true;
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n == 0) {
            int s = sum * k / n;
            if (dp[k][n][s]) {
                return true;
            }
        }
    }

    return false;
}

