public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        String substr = s.substring(i, i + k);
        int value = Integer.parseInt(substr, 2);
        found[value] = true;
    }

    for (boolean isFound : found) {
        if (!isFound) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || k > s.length()) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] seen = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        int num = 0;
        for (int j = i; j < i + k; j++) {
            num = (num << 1) + (s.charAt(j) - '0');
        }
        seen[num] = true;
    }

    for (boolean isPresent : seen) {
        if (!isPresent) {
            return false;
        }
    }

    return true;
}

