public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    boolean[] seen = new boolean[1 << k];
    int val = 0;
    int mask = (1 << k) - 1;

    for (int i = 0; i < s.length(); i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1 && !seen[val]) {
            seen[val] = true;
        }
    }

    for (boolean code : seen) {
        if (!code) {
            return false;
        }
    }

    return true;
}

