public int minInsertions(String s) {
    int left = 0; // Number of unmatched '('
    int right = 0; // Number of needed ')' to make balanced
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                // If we have an unmatched ')', we need to insert '(' to balance it
                left++;
                right--;
            }
            right += 2; // Every '(' needs two ')'
        } else {
            right--; // Match one ')'
            if (right == -1) {
                // If we have more ')' than needed, we need to insert '('
                left++;
                right = 1; // We need one more ')' to balance the inserted '('
            }
        }
    }
    return left + right;
}

public int minInsertions(String s) {
    int left = 0; // Tracks the number of unmatched '('
    int right = 0; // Tracks the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            // Each '(' needs two ')'
            if (right % 2 == 1) {
                // If we have an odd number of right insertions needed, we need to insert a ')'
                right++;
                left--;
            }
            left++;
        } else {
            // Encountered a ')'
            right++;
            if (right == 2) {
                // We have a complete pair of ')'
                right = 0;
                if (left > 0) {
                    // Match with a '('
                    left--;
                } else {
                    // Need an additional '('
                    right++;
                }
            }
        }
    }

    // Each remaining '(' needs two ')'
    return left * 2 + right;
}

public int minInsertions(String s) {
    int left = 0; // Number of '('
    int right = 0; // Number of need ')'
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                // Need to insert a ')' to balance
                left--;
                right++;
            }
            left++;
            right -= 2;
        } else {
            right++;
            if (right == 2 && left > 0) {
                // Balance one '('
                left--;
                right = 0;
            }
        }
    }
    return left * 2 + right;
}

public int minInsertions(String s) {
    int open = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
            if (i < s.length() - 1 && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it forms a valid pair with the current ')'
            } else {
                insertions++; // Need to insert a ')' to balance the current '('
            }
        }
    }

    return insertions + open;
}

public int minInsertions(String s) {
    int leftNeed = 0; // To count the number of '(' needed
    int rightNeed = 0; // To count the number of ')' needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            rightNeed += 2; // Each '(' needs two ')'
            // If rightNeed is odd, we need an extra ')' to make it balanced
            if (rightNeed % 2 == 1) {
                rightNeed--; // We insert a ')' here
                leftNeed++; // We also need a '(' before this inserted ')'
            }
        } else if (c == ')') {
            rightNeed--; // One ')' is matched
            if (rightNeed == -1) {
                leftNeed++; // Need to insert a '(' to match this ')'
                rightNeed = 1; // Reset rightNeed to 1 as we inserted a '('
            }
        }
    }

    return leftNeed + rightNeed; // Total insertions needed
}

