        throw new IllegalArgumentException("Both n and k must be positive integers.");
    }

    int factorCount = 0;

    // Check for factors from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factorCount++;
            if (factorCount == k) {
                return i;
            }
            // Check if the corresponding factor is different and count it
            if (i != n / i) {
                int correspondingFactor = n / i;
                if (factorCount + 1 == k) {
                    return correspondingFactor;
                }
            }
        }
    }

    return -1; // If fewer than k factors are found
}

