public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (n > 0) {
        int remaining = k - 26 * (n - 1);
        if (remaining > 0) {
            char c = (char)('a' + remaining - 1);
            result.append(c);
            k -= remaining;
        } else {
            result.append('a');
            k -= 1;
        }
        n--;
    }
    return result.toString();
}

