    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n; // Adjust k to account for the initial 'a's
    int index = n - 1;
    while (k > 0) {
        int add = Math.min(25, k); // Add the maximum possible value to make the lexicographically smallest string
        result.setCharAt(index, (char) ('a' + add));
        k -= add;
        index--;
    }
    return result.toString();
}

