    for (int i = 1; i <= n; i++) {
        if (remainingValue > 25) {
            result.append('z');
            remainingValue -= 25;
        } else {
            result.append((char) ('a' + remainingValue));
            remainingValue = 0;
        }
    }
    if (remainingValue != 0) {
        throw new IllegalArgumentException("Invalid input: no valid string can be formed with the given n and k.");
    }
    return result.reverse().toString();
}

