    // Start from the end of the string and change 'a' to the required character
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        // Calculate the maximum character value that can be used here
        int addValue = Math.min(25, k);
        // Append the character that corresponds to the current addValue
        result.setCharAt(i, (char) ('a' + addValue));
