    for (long m = 1; m <= n; m *= 10) {
        long a = n / m, b = n % m;
        count += (a + 8) / 10 * m + (a % 10 == 1 ? b + 1 : 0);
    }
    return count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (int i = 1; i <= n; i *= 10) {
        int divider = i * 10;
        count += (n / divider) * i + Math.min(Math.max(n % divider - i + 1, 0), i);
    }
    return count;
}

