public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, it means digits are in descending order
    // and no larger number can be formed
    if (i == -1) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of (i-th digit)
    // that is greater than digits[i]
    int j;
    for (j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Step 3: Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the digits after (i-th digit)
    String str = new String(digits);
    str = str.substring(0, i + 1) + new StringBuilder(str.substring(i + 1)).reverse().toString();

    // Convert the result to an integer
    try {
        return Integer.parseInt(str);
    } catch (NumberFormatException e) {
        // In case the number is out of integer range, return -1
        return -1;
    }
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Traverse the array from the second last digit to the beginning
    for (int i = len - 2; i >= 0; i--) {
        // If the current digit is smaller than the next digit
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of (i-th digit) that is larger than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }
            // Swap the found smallest digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the (i-th digit) in ascending order
            Arrays.sort(digits, i + 1, len);

            // Convert the char array back to integer and return
            try {
                return Integer.parseInt(new String(digits));
            } catch (NumberFormatException e) {
                return -1;
            }
        }
    }

    // If no rearrangement is possible that results in a greater number
    return -1;
}

